int maxCoins(int** piles, int pilesSize, int* pilesColSize, int k){
    int* pq = malloc(sizeof(int) * 2000);
    int pqSize = 0;
    for (int i = 0; i < pilesSize; i++) {
        for (int j = 0; j < pilesColSize[i]; j++) {
